package com.gathin.tvhome;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import org.junit.Test;

import java.nio.charset.StandardCharsets;

/**
 * Module-for-module against segno 1.6.6 (error M, byte mode, the given mask), with one fix to segno:
 * it adds 8 zero padding bits when the bit stream already ends on a byte boundary (always the case for
 * byte mode), where ISO/IEC 18004 7.4.10 adds none. Both decode the same; this encoder follows the spec.
 */
public class QrTest {

    private static void check(String data, int mask, String expected) {
        boolean[][] m = Qr.encode(data.getBytes(StandardCharsets.UTF_8), mask);
        assertNotNull(m);
        StringBuilder sb = new StringBuilder();
        for (int y = 0; y < m.length; y++) {
            if (y > 0) sb.append('|');
            for (boolean b : m[y]) sb.append(b ? '1' : '0');
        }
        assertEquals(data + " mask " + mask, expected, sb.toString());
    }

    @Test
    public void matchesSegno() {
        // 'http://192.168.1.13:8080/?k=123456' mask 0 -> version 3
        check("http://192.168.1.13:8080/?k=123456", 0, "11111110011101001101101111111|10000010110100111101001000001|10111010011001101010101011101|10111010010001110001101011101|10111010110000100001101011101|10000010000001000101001000001|11111110101010101010101111111|00000000011101101101000000000|10101010001100111111000010010|01101000111010110000001101001|10100010100001001100111110111|01110100101010001110011101010|01110011010010000111001101011|00010001001101000010001101101|01101111110010100100000000011|01010001101011111110010011010|10100010011110100100001000011|01000000000000100000011100101|10111011011001001110010001011|01010100001100011111011101010|10000110000010000110111110000|00000000101001000010100010111|11111110011000100001101011011|10000010001001100111100011011|10111010111010100110111111001|10111010001010100111110011011|10111010111000001011010011101|10000010010111100111110001010|11111110100110000110111001011");
        // 'http://192.168.1.13:8080/?k=123456' mask 5 -> version 3
        check("http://192.168.1.13:8080/?k=123456", 5, "11111110001000011000101111111|10000010100011101010001000001|10111010100001010010001011101|10111010101110001110001011101|10111010001000011001001011101|10000010010110010010001000001|11111110101010101010101111111|00000000101010111010000000000|10000010110100000111111001110|10010101000101001111110010110|10011010011001110100000110000|10100001111101011001001010000|00100110000111010010011000001|11000100011010010101011010111|01010111001010011100111000100|10101100010100000001101100101|10011010100110011100110000100|10010101010111110111001011111|11101110001100011011000100001|10000001011011001000001010000|10111110111010111110111110111|00000000110110111101100011000|11111110000000011001101011100|10000010011110110000100010001|10111010001111110011111110011|10111010011101110000100100001|10111010000000110011101011010|10000010001000011000001110101|11111110111110111110000001100");
        // 'Hello' mask 3 -> version 1
        check("Hello", 3, "111111101111101111111|100000101101001000001|101110100100001011101|101110101010001011101|101110100001001011101|100000100011101000001|111111101010101111111|000000001111100000000|101101110011101001011|000100001001111001101|100010101011000000011|111111001101001111010|011100111110100100001|000000001101001000101|111111101011100100000|100000101010000111110|101110100100111111111|101110101011001011110|101110101100101100100|100000100000010110001|111111101010010100100");
        // 'http://192.168.100.200:65535/?k=000000&extra=padding-long-12345678' mask 6 -> version 5
        check("http://192.168.100.200:65535/?k=000000&extra=padding-long-12345678", 6, "1111111011100001110111110100101111111|1000001010100001001100111110101000001|1011101010111110101101010111001011101|1011101001001001111001110111001011101|1011101011000000100111101000001011101|1000001000110011000000111000101000001|1111111010101010101010101010101111111|0000000000011001111110110101100000000|1001111111011101000101101000110010111|1010000111100010101000001001100111010|0011011000101101111111111011110000001|0000000100001100111110011001001111111|0100001011001001001000100011111000001|1100110111001011100011111101010111010|0001101000001001101110001001111001101|0110110100111000100001111010110011111|0111111001101000011101100110011000111|0110110000000000010000101011010100100|1011001101101100111100110111111011101|1111110111110101101110110111100101001|1000011001001100011110100000001011000|1001100111010001010110011011100010100|1101111000010001100001011111000101001|0100100000010100001100011011001110110|1000101110000011010011110011101100011|1100000001011110001100111001100010000|1110101100100001001001001011010100111|1000010011101110101100010011000111100|1000001001110101001110010110111111111|0000000010001111010111101011100010000|1111111011001101111100011100101011001|1000001011110001100001001110100010001|1011101010011001101011000001111111011|1011101010111110000011111001101001101|1011101001001100011000110111000011001|1000001001011011011000010000000111111|1111111011000000101100110010111001001");
    }

    @Test
    public void picksSomeMaskAndRefusesTooLong() {
        assertNotNull(Qr.encode("http://192.168.1.13:8080/?k=123456".getBytes(StandardCharsets.UTF_8)));
        assertNull(Qr.encode(new byte[85]));
    }
}
